-- Контент 1º и 2º ESO. Сгенерировано scripts/build_content_sql.py из content/eso_topics.py.
-- Требует проверки учителем.

update public.topics set subject = 'Biología y Geología' where id = 'bio-celula';
update public.topics set sort = 4 where id = 'mat-fracciones';
update public.topics set sort = 2 where id = 'bio-celula';

on conflict (id) do update set grade=excluded.grade, subject=excluded.subject, subject_code=excluded.subject_code, title=excluded.title, title_ru=excluded.title_ru, title_en=excluded.title_en, sort=excluded.sort;
on conflict (id) do update set es=excluded.es, ru=excluded.ru, en=excluded.en, teacher=excluded.teacher, sort=excluded.sort;